import { NextResponse } from "next/server";

/**
 * Lead capture + live agent provisioning.
 *
 * The landing form POSTs the lead here. We proxy it to the proven provision
 * endpoint (nanohub_demo), which holds the encrypted provision token + tunnel
 * URL and spawns a fresh NanoClaw agent, returning a Telegram deep link.
 *
 * On any failure we degrade to { status: "pending" } so the user flow never
 * breaks (the front end then shows the "הסוכן שלך בהכנה" state).
 */
const PROVISION = "https://nanohubdemo.vercel.app/api/register";

type Lead = {
  name?: string;
  firstname?: string;
  lastname?: string;
  phone?: string;
  email?: string;
  lang?: string;
};

export async function POST(request: Request) {
  let lead: Lead = {};
  try {
    lead = (await request.json()) as Lead;
  } catch {
    // tolerate empty / malformed body
  }
  lead = lead || {};

  const name =
    (lead.name && lead.name.trim()) ||
    `${lead.firstname || ""} ${lead.lastname || ""}`.trim();

  try {
    const r = await fetch(PROVISION, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name,
        phone: lead.phone || "",
        email: lead.email || "",
        lang: lead.lang || "he",
      }),
    });
    if (r.ok) {
      const j = await r.json().catch(() => ({} as Record<string, unknown>));
      const deepLink = (j as { deepLink?: string }).deepLink;
      const status = (j as { status?: string }).status;
      if (deepLink) {
        return NextResponse.json(
          { status: status || "live", deepLink },
          { status: 200 }
        );
      }
      return NextResponse.json({ status: status || "pending" }, { status: 200 });
    }
  } catch {
    // fall through to pending
  }

  return NextResponse.json({ status: "pending" }, { status: 200 });
}

